(84, 'en', 'elementor-317', 'html-html-db95f27', '<script type=\'text/javascript\' src=\'//op.europa.eu/o/opportal-widgets/js/widget/widgetload.js\'></script>\n<script type=\'application/json\'>\n{\"portalURL\":\"//op.europa.eu\",\"uuid\":\"portal201248372d7c5a65412ea3e9ab6d2ce4d627\",\"widgetId\":\"8623\",\"widgetType\":\"1\"}\n</script>\n', 6, 1, '', 'AREA', 'HTML', 10, '', '9d18dbe9b8ae60e8ac85f71bf527c043', 'optional', 12, 0, NULL, 0),
(87, 'en', 'elementor-15', 'html-html-b3e2eb2', '<form id=\"openai-form\">\n    <textarea id=\"user-input\" name=\"user_input\" placeholder=\"Ask Brubru anything...\"></textarea>\n    <button type=\"submit\">Send</button>\n</form>\n<div id=\"openai-response\"></div>\n\n<script>\n    document.getElementById(\'openai-form\').addEventListener(\'submit\', function(e) {\n        e.preventDefault();\n        const userInput = document.getElementById(\'user-input\').value;\n\n        fetch(\'<?php echo admin_url(\"admin-ajax.php\"); ?>\', {\n            method: \'POST\',\n            headers: { \'Content-Type\': \'application/x-www-form-urlencoded\' },\n            body: new URLSearchParams({\n                action: \'brubru_openai_chat\',\n                user_input: userInput,\n            }),\n        })\n        .then(response => response.text())\n        .then(data => document.getElementById(\'openai-response\').innerText = data)\n        .catch(err => console.error(err));\n    });\n</script>\n', 1, 5, '', 'AREA', 'HTML', 0, '', 'f86774769e11cffc240278a37a468455', 'optional', 69, 0, NULL, 0);
