(46, 59, 'fr', 10, '[all-fields]', NULL, NULL, 'local', 0, '2024-11-26 16:04:47'),
(47, 60, 'fr', 10, 'Votre demande a été acceptée.', NULL, NULL, 'local', 0, '2024-11-26 16:04:47'),
(48, 61, 'fr', 10, 'Votre soumission a échoué en raison d\'une erreur.', NULL, NULL, 'local', 0, '2024-11-26 16:04:47'),
(49, 62, 'fr', 10, 'Votre soumission a échoué car le formulaire n\'est pas valide.', NULL, NULL, 'local', 0, '2024-11-26 16:04:47'),
