(2015, 'wpml_config_files_arr', 'O:8:\"stdClass\":2:{s:6:\"themes\";a:0:{}s:7:\"plugins\";a:3:{s:9:\"Elementor\";s:35093:\"<wpml-config>\n   <custom-fields>\n        <custom-field action=\"copy-once\">_elementor_page_settings</custom-field>\n        <custom-field action=\"copy\">_elementor_edit_mode</custom-field>\n        <custom-field action=\"copy\">_elementor_template_type</custom-field>\n        <custom-field action=\"copy\">_elementor_version</custom-field>\n        <custom-field action=\"copy-once\">_elementor_data</custom-field>\n        <custom-field action=\"ignore\">_elementor_css</custom-field>\n        <custom-field action=\"copy\">_elementor_edit_mode</custom-field>\n        <custom-field action=\"copy-once\">_elementor_popup_display_settings</custom-field>\n    </custom-fields>\n    <custom-types>\n        <custom-type translate=\"1\" display-as-translated=\"1\">elementor_library</custom-type>\n        <custom-type translate=\"1\" display-as-translated=\"1\">e-landing-page</custom-type>\n        <custom-type translate=\"1\" display-as-translated=\"1\">e-floating-buttons</custom-type>\n    </custom-types>\n    <taxonomies>\n        <taxonomy translate=\"0\">elementor_library_type</taxonomy>\n    </taxonomies>\n    <elementor-widgets>\n        <widget name=\"stripe-button\">\n            <fields>\n                <field type=\"Stripe button: Product name\">product_name</field>\n                <field type=\"Stripe button: Button text\">text</field>\n                <field type=\"Stripe button: Global error message\">error_message_global</field>\n                <field type=\"Stripe button: Payment error message\">error_message_payment</field>\n                <field type=\"Stripe button: Redirect after success URL\" editor_type=\"LINK\">redirect_after_success>url</field>\n            </fields>\n        </widget>\n        <widget name=\"paypal-button\">\n            <fields>\n                <field type=\"PayPal button: Product name\">product_name</field