(2386, 'otgs_active_components', 'a:2:{s:6:\"plugin\";a:14:{i:0;a:3:{s:4:\"File\";s:23:\"ai-engine/ai-engine.php\";s:4:\"Name\";s:9:\"AI Engine\";s:7:\"Version\";s:5:\"3.1.1\";}i:1;a:3:{s:4:\"File\";s:31:\"code-snippets/code-snippets.php\";s:4:\"Name\";s:13:\"Code Snippets\";s:7:\"Version\";s:5:\"3.7.0\";}i:2;a:3:{s:4:\"File\";s:37:\"disable-comments/disable-comments.php\";s:4:\"Name\";s:16:\"Disable Comments\";s:7:\"Version\";s:5:\"2.5.3\";}i:3;a:3:{s:4:\"File\";s:29:\"easy-wp-smtp/easy-wp-smtp.php\";s:4:\"Name\";s:12:\"Easy WP SMTP\";s:7:\"Version\";s:6:\"2.12.0\";}i:4;a:3:{s:4:\"File\";s:23:\"elementor/elementor.php\";s:4:\"Name\";s:9:\"Elementor\";s:7:\"Version\";s:6:\"3.32.3\";}i:5;a:3:{s:4:\"File\";s:29:\"pro-elements/pro-elements.php\";s:4:\"Name\";s:12:\"PRO Elements\";s:7:\"Version\";s:6:\"3.29.0\";}i:6;a:3:{s:4:\"File\";s:27:\"sg-security/sg-security.php\";s:4:\"Name\";s:18:\"Security Optimizer\";s:7:\"Version\";s:5:\"1.5.7\";}i:7;a:3:{s:4:\"File\";s:31:\"sg-cachepress/sg-cachepress.php\";s:4:\"Name\";s:15:\"Speed Optimizer\";s:7:\"Version\";s:5:\"7.7.2\";}i:8;a:3:{s:4:\"File\";s:27:\"svg-support/svg-support.php\";s:4:\"Name\";s:11:\"SVG Support\";s:7:\"Version\";s:6:\"2.5.14\";}i:9;a:3:{s:4:\"File\";s:35:\"insert-headers-and-footers/ihaf.php\";s:4:\"Name\";s:11:\"WPCode Lite\";s:7:\"Version\";s:5:\"2.3.0\";}i:10;a:3:{s:4:\"File\";s:40:\"sitepress-multilingual-cms/sitepress.php\";s:4:\"Name\";s:21:\"WPML Multilingual CMS\";s:7:\"Version\";s:5:\"4.8.2\";}i:11;a:3:{s:4:\"File\";s:30:\"wp-seo-multilingual/plugin.php\";s:4:\"Name\";s:8:\"WPML SEO\";s:7:\"Version\";s:5:\"2.2.4\";}i:12;a:3:{s:4:\"File\";s:34:\"wpml-string-translation/plugin.php\";s:4:\"Name\";s:23:\"WPML String Translation\";s:7:\"Version\";s:5:\"3.4.1\";}i:13;a:3:{s:4:\"File\";s:24:\"wordpress-seo/wp-seo.php\";s:4:\"Name\";s:9:\"Yoast SEO\";s:7:\"Version\";s:4:\"26.0\";}}s:5:\"theme\";a:1:{i:0;a:3:{s:8:\"Template\";s:15:\"hello-elementor\";s:4:\"Name\";s:15:\"Hello Elementor\";s:7:\"Version\";s