os\":{\"unit\":\"vw\",\"size\":75,\"sizes\":[]},\"background_xpos_tablet\":{\"unit\":\"%\",\"size\":0,\"sizes\":[]},\"background_xpos_mobile\":{\"unit\":\"%\",\"size\":0,\"sizes\":[]},\"background_repeat\":\"repeat-y\",\"background_size\":\"initial\",\"background_bg_width\":{\"unit\":\"%\",\"size\":20,\"sizes\":[]},\"background_motion_fx_translateY_speed\":{\"unit\":\"px\",\"size\":10,\"sizes\":[]},\"background_overlay_xpos_tablet\":{\"unit\":\"%\",\"size\":0,\"sizes\":[]},\"background_overlay_xpos_mobile\":{\"unit\":\"%\",\"size\":0,\"sizes\":[]},\"presetTitle\":\"Grid\",\"presetIcon\":\"eicon-container-grid\",\"_element_id\":\"about\",\"padding_tablet\":{\"unit\":\"px\",\"top\":\"40\",\"right\":\"40\",\"bottom\":\"40\",\"left\":\"40\",\"isLinked\":true},\"grid_gaps_tablet\":{\"column\":\"40\",\"row\":\"40\",\"isLinked\":true,\"unit\":\"px\"}},\"elements\":[{\"id\":\"d9d0d0e\",\"elType\":\"container\",\"settings\":{\"content_width\":\"full\",\"padding\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":true}},\"elements\":[{\"id\":\"d388a2d\",\"elType\":\"widget\",\"settings\":{\"content_width\":\"full\",\"title\":\"About<br>Brubru\",\"typography_typography\":\"custom\",\"typography_font_family\":\"Roboto\",\"typography_font_size\":{\"unit\":\"px\",\"size\":55,\"sizes\":[]},\"typography_font_weight\":\"600\",\"__globals__\":{\"title_color\":\"globals\\/colors?id=secondary\"},\"typography_font_size_mobile\":{\"unit\":\"px\",\"size\":40,\"sizes\":[]}},\"elements\":[],\"widgetType\":\"heading\"},{\"id\":\"07c3f54\",\"elType\":\"widget\",\"settings\":{\"content_width\":\"full\",\"editor\":\"<p>Brubru est\\u00e0 dissenyat per desmitificar la naturalesa complexa i burocr\\u00e0tica de les institucions de la UE, oferint una orientaci\\u00f3 estrat\\u00e8gica per a una incid\\u00e8ncia i un lobby efectius a Brussel\\u00b7les. Brubru ajuda a qui ho necessiti a defensar les seves necessitats davant les principals institucions i funcionaris de la Uni\\u00f3 Europea, a fer esmenes i resolucions, a con\\u00e8ixer com funcionen els processos legislatius de la Uni\\u00f3 Europea i com no perdre\'s en el laberint de la bombolla de la UE.<\\/p>\\n\",\"_element_width\":\"initial\",\"_element_custom_width\":{\"unit\":\"px\",\"size\":410,\"sizes\":[]},\"__globals__\":{\"text_color\":\"globals\\/colors?id=secondary\"}},\"elements\":[],\"widgetType\":\"text-editor\"}],\"isInner\":true},{\"id\":\"b3cdf6f\",\"elType\":\"widget\",\"settings\":{\"content_width\":\"full\",\"image\":{\"url\":\"http:\\/\\/brubru.world\\/wp-content\\/uploads\\/2024\\/10\\/brubru-aboutus.svg\",\"id\":53,\"size\":\"\",\"alt\":\"\",\"source\":\"library\"}},\"elements\":[],\"widgetType\":\"image\"}],\"isInner\":false},{\"id\":\"6c975a1\",\"elType\":\"container\",\"settings\":{\"content_width\":\"full\",\"min_height\":{\"unit\":\"vh\",\"size\":\"\",\"sizes\":[]},\"min_height_tablet\":{\"unit\":\"vh\",\"size\":\"\",\"sizes\":[]},\"min_height_mobile\":{\"unit\":\"vh\",\"size\":\"\",\"sizes\":[]},\"background_background\":\"classic\",\"padding\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":true},\"__globals__\":{\"background_color\":\"globals\\/colors?id=primary\"},\"flex_align_items\":\"flex-end\",\"background_image\":{\"url\":\"\",\"id\":\"\",\"size\":\"\",\"alt\":\"\",\"source\":\"library\"},\"background_xpos_tablet\":{\"unit\":\"%\",\"size\":0,\"sizes\":[]},\"background_xpos_mobile\":{\"unit\":\"%\",\"size\":0,\"sizes\":[]},\"background_motion_fx_translateY_speed\":{\"unit\":\"px\",\"size\":10,\"sizes\":[]},\"background_overlay_xpos_tablet\":{\"unit\":\"%\",\"size\":0,\"sizes\":[]},\"background_overlay_xpos_mobile\":{\"unit\":\"%\",\"size\":0,\"sizes\":[]}},\"elements\":[{\"id\":\"b99496b\",\"elType\":\"container\",\"settings\":{\"content_width\":\"full\",\"width\":{\"unit\":\"%\",\"size\":90,\"sizes\":[]},\"boxed_width\":{\"unit\":\"%\",\"size\":60,\"sizes\":[]},\"boxed_width_tablet\":{\"unit\":\"%\",\"size\":\"\",\"sizes\":[]},\"boxed_width_mobile\":{\"unit\":\"%\",\"size\":\"\",\"sizes\":[]},\"min_height\":{\"unit\":\"vh\",\"size\":\"\",\"sizes\":[]},\"min_height_tablet\":{\"unit\":\"vh\",\"size\":\"\",\"sizes\":[]},\"min_height_mobile\":{\"unit\":\"vh\",\"size\":\"\",\"sizes\":[]},\"flex_justify_content\":\"center\",\"flex_align_items\":\"center\",\"background_background\":\"classic\",\"padding\":{\"unit\":\"px\",\"top\":\"60\",\"right\":\"40\",\"bottom\":\"60\",\"left\":\"80\",\"isLinked\":false},\"__globals__\":{\"background_color\":\"globals\\/colors?id=secondary\"},\"container_type\":\"grid\",\"grid_columns_grid\":{\"unit\":\"fr\",\"size\":2,\"sizes\":[]},\"grid_rows_grid\":{\"unit\":\"fr\",\"size\":1,\"sizes\":[]},\"grid_gaps\":{\"column\":\"150\",\"row\":\"150\",\"isLinked\":true,\"unit\":\"px\"},\"grid_align_items\":\"center\",\"presetTitle\":\"Grid\",\"presetIcon\":\"eicon-container-grid\",\"grid_gaps_tablet\":{\"column\":\"40\",\"row\":\"40\",\"isLinked\":true,\"unit\":\"px\"},\"padding_tablet\":{\"unit\":\"px\",\"top\":\"40\",\"right\":\"40\",\"bottom\":\"40\",\"left\":\"40\",\"isLinked\":true}},\"elements\":[{\"id\":\"bf9dbdc\",\"elType\":\"widget\",\"settings\":{\"content_width\":\"full\",\"image\":{\"url\":\"http:\\/\\/brubru.world\\/wp-content\\/uploads\\/2024\\/10\\/brubru-aboutme.svg\",\"id\":58,\"size\":\"\",\"alt\":\"\",\"source\":\"library\"}},\"elements\":[],\"widgetType\":\"image\"},{\"id\":\"0bf8472\",\"elType\":\"container\",\"settings\":{\"content_width\":\"full\",\"flex_justify_content\":\"center\",\"padding\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":true}},\"elements\":[{\"id\":\"281808a\",\"elType\":\"widget\",\"settings\":{\"content_width\":\"full\",\"title\":\"Sobre mi\",\"typography_typography\":\"custom\",\"typography_font_family\":\"Roboto\",\"typography_font_size\":{\"unit\":\"px\",\"size\":55,\"sizes\":[]},\"typography_font_weight\":\"600\",\"__globals__\":{\"ti