INSERT INTO `xnh_snippets` (`id`, `name`, `description`, `code`, `tags`, `scope`, `priority`, `active`, `modified`, `revision`, `cloud_id`, `condition_id`) VALUES
(1, 'Make upload filenames lowercase', 'Makes sure that image and file uploads have lowercase filenames.\n\nThis is a sample snippet. Feel free to use it, edit it, or remove it.', 'add_filter( \'sanitize_file_name\', \'mb_strtolower\' );', 'sample, media', 'global', 10, 0, '2024-11-26 16:07:41', 2, NULL, 0),
(2, 'Disable admin bar', 'Turns off the WordPress admin bar for everyone except administrators.\n\nThis is a sample snippet. Feel free to use it, edit it, or remove it.', 'add_action( \'wp\', function () {\n	if ( ! current_user_can( \'manage_options\' ) ) {\n		show_admin_bar( false );\n	}\n} );', 'sample, admin-bar', 'front-end', 10, 0, '2024-11-26 16:07:41', 2, NULL, 0),
(3, 'Allow smilies', 'Allows smiley conversion in obscure places.\n\nThis is a sample snippet. Feel free to use it, edit it, or remove it.', 'add_filter( \'widget_text\', \'convert_smilies\' );\nadd_filter( \'the_title\', \'convert_smilies\' );\nadd_filter( \'wp_title\', \'convert_smilies\' );\nadd_filter( \'get_bloginfo\', \'convert_smilies\' );', 'sample', 'global', 10, 0, '2024-11-26 16:07:41', 2, NULL, 0),
(4, 'Current year', 'Shortcode for inserting the current year into a post or page..\n\nThis is a sample snippet. Feel free to use it, edit it, or remove it.', '<?php echo date( \'Y\' ); ?>', 'sample, dates', 'content', 10, 0, '2024-11-26 16:07:41', 2, NULL, 0),
(5, 'Brubru snippet', '', 'function brubru_openai_request($user_input) {\n    $api_key = \'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\'; // Replace with your OpenAI API key\n    $endpoint = \'https://api.openai.com/v1/completions\';\n\n    $response = wp_remote_post($endpoint, [\n        \'headers\' => [\n            \'Content-Type\' => \'application/json\',\n            \'Authorization\' => \'Bearer \' . $api_key,\n        ],\n        \'body\' => json_encode([\n            \'model\' => \'text-davinci-003\', // Adjust model if needed\n            \'prompt\' => $user_input,\n            \'max_tokens\' => 100,\n            \'temperature\' => 0.7,\n        ]),\n    ]);\n\n    if (is_wp_error($response)) {\n        return \'Error: \' . $response->get_error_message();\n    }\n\n    $body = json_decode(wp_remote_retrieve_body($response), true);\n\n    return isset($body[\'choices\'][0][\'text\']) ? $body[\'choices\'][0][\'text\'] : \'No response from OpenAI.\';\n}\nfunction brubru_openai_chat_ajax() {\n    if (!isset($_POST[\'user_input\'])) {\n        echo \'No input received.\';\n        wp_die();\n    }\n\n    $user_input = sanitize_text_field($_POST[\'user_input\']);\n    $response = brubru_openai_request($user_input);\n    echo $response;\n    wp_die();\n}\nadd_action(\'wp_ajax_brubru_openai_chat\', \'brubru_openai_chat_ajax\');\nadd_action(\'wp_ajax_nopriv_brubru_openai_chat\', \'brubru_openai_chat_ajax\');\n\n', '', 'global', 10, 1, '2024-12-05 11:04:00', 5, NULL, 0);
